function runDataIOInterop(Directory, Writers)
% Write and check file-exchange cases through the public MATLAB API.
%
% INPUT
% Directory  Existing folder with files generated by interop.R and interop.py.
% Writers  Optional cell vector of writer names, including 'julia'.
%
% OUTPUT
% Four MATLAB output files. Files from the selected writers are checked.
% A failed check raises an error. The MATLAB path is restored on exit.
% SPDX-License-Identifier: AGPL-3.0-only
% Additional permission: see MATLAB-EXCEPTION.txt.

OriginalPath = path;
if nargin < 2, Writers = {'r','python','matlab'}; end
RestorePath = onCleanup(@() path(OriginalPath)); %#ok<NASGU>
setupDataIO('modern');
Key = [-2^53;2^31;2^53];
Values = [1.25 10;NaN -2.5;3.75 30];
Classes = [2;NaN;1];
Names = {'1.0.4';'';char([77 252 110 99 104 101 110])};
Texts = {'A1','B1';'','B2';'A3',''};
Times = {'2024-10-27 00:30:00.125';'2024-06-15 13:45:10.250';'2024-10-27 01:30:00.999'};
Comment = 'language exchange';
WriteLRN('matlab',Values,{'X','Y'},Key,[],Directory,Comment,false,[],struct('SignificantDigits',15));
WriteCLS('matlab',Classes,Key,Directory,Comment);
WriteNAMES('matlab',Names,Key,Texts,Directory,{'Names','Extra1','Extra2'},Comment);
WriteDates('matlab',Times,Values,{'X','Y'},Key,Directory,Comment,struct('Format',3));
Names{2} = 'NA'; Texts{2,1} = 'NA'; Texts{3,2} = 'NA';
for I = 1:numel(Writers)
    Writer = Writers{I};
    [A,K,H,~,C] = ReadLRN([Writer '.lrn'],Directory);
    assert(isequal(K,Key) && isequaln(A,Values));
    assert(isequal(cellstr(H),{'X';'Y'}) && strcmp(C,Comment));
    fprintf('PASS %s -> MATLAB: lrn\n',Writer);
    [K,A,C] = ReadCLS([Writer '.cls'],Directory);
    assert(isequal(K,Key) && isequaln(A,Classes) && strcmp(C,Comment));
    fprintf('PASS %s -> MATLAB: cls\n',Writer);
    [K,N,~,C,H,T] = ReadNAMES([Writer '.names'],Directory);
    assert(isequal(K,Key) && isequal(cellstr(N),Names) && isequal(T,Texts));
    assert(isequal(cellstr(H),{'Key';'Names';'Extra1';'Extra2'}) && strcmp(C,Comment));
    fprintf('PASS %s -> MATLAB: names\n',Writer);
    [T,A,K,H,C,Zone] = ReadDates([Writer '.dts'],Directory);
    assert(isequal(K,Key) && isequaln(A,Values) && isequal(T,Times));
    assert(isequal(cellstr(H),{'X';'Y'}) && strcmp(C,Comment) && strcmp(Zone,'UTC'));
    fprintf('PASS %s -> MATLAB: dts\n',Writer);
end
end
